import java.util.*;

class Solution {
    private List<int[]> pts = new ArrayList<>();

    public List<List<Integer>> verticalTraversal(TreeNode root) {
        walk(root, 0, 0);
        // sort by column, then row, then value
        Collections.sort(pts, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]);
        List<List<Integer>> out = new ArrayList<>();
        Integer lastCol = null;
        for (int[] p : pts) {
            if (lastCol == null || p[0] != lastCol) { // new column starts
                out.add(new ArrayList<Integer>());
                lastCol = p[0];
            }
            out.get(out.size() - 1).add(p[2]);
        }
        return out;
    }

    private void walk(TreeNode n, int row, int col) {
        if (n == null) return;
        pts.add(new int[]{col, row, n.val});
        walk(n.left, row + 1, col - 1);
        walk(n.right, row + 1, col + 1);
    }
}

