class Solution:
    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        pts, q = [], [(root, 0, 0)]
        while q:
            n, r, c = q.pop()
            pts.append((c, r, n.val))
            if n.left: q.append((n.left, r + 1, c - 1))
            if n.right: q.append((n.right, r + 1, c + 1))
        pts.sort(); out = []; last = None
        for c, r, v in pts:
            if c != last: out.append([]); last = c
            out[-1].append(v)
        return out

