  const m = new Map();
  const go = (n, r, c) => { if (!n) return; if (!m.has(c)) m.set(c, []); m.get(c).push([r, n.val]); go(n.left, r + 1, c - 1); go(n.right, r + 1, c + 1); };
  go(root, 0, 0);
  return [...m.keys()].sort((a, b) => a - b).map(c => m.get(c).sort((x, y) => x[0] - y[0] || x[1] - y[1]).map(x => x[1]));
